'use strict';
const PRODUCTS_UI6={bind,coffeeView,brandingView,help,digestDestination6,performanceDetail5};let coffeeTab6='recipes';
TITLES.coffee='Káva & vlastní produkty';document.querySelector('[data-view="coffee"] span').textContent='Káva & vlastní produkty';
function productsView6(){const f=state.products6,last=f.last;return `<p class="intro">Vyviň hotový produkt, zabal skutečnou upraženou kávu a doprav celé balíčky na prodejny. E-shop prodává ze stejného skladu hotových balení. Změny receptury ovlivní nové balení; staré šarže si zachovají náklad, značku a kvalitu.</p><div class="report-overview5">${metric('HOTOVÁ BALENÍ',f.lots.reduce((n,l)=>n+l.units,0),'Ve skladu, na cestě a v kavárnách')}${metric('PRODÁNO MINULE',last?last.rows.reduce((n,p)=>n+p.units,0):'—','Celé kusy; kavárny a e-shop')}${metric('TRŽBY BEZ DPH',last?money(last.rows.reduce((n,p)=>n+p.revenue,0)):'—','Balená káva · 12% DPH')}${metric('PŘÍSPĚVEK',last?money(last.rows.reduce((n,p)=>n+p.contribution,0)):'—','Po spotřebovaných zásobách a expedici')}</div><div class="actions"><button class="primary" id="productNew6">Vyvinout produkt +</button><button class="soft" id="productReport6">Otevřít report produktů</button><button class="soft" data-goto="lab">Laboratoř receptur</button><button class="soft" data-goto="roasters">Pražení a zásoby</button><button class="soft" data-goto="hq">Spustit e-shop přes IT</button></div><p class="sub">Vývoj spotřebuje 500 g vzorku a stojí ${state.departments.product?'3 500':'6 000'} Kč. Test trvá dva týdny a vyžaduje kvalitu 65/100. Balení potřebuje kvalitu nejméně 50/100. Obal drží kávu nejvýše 16 týdnů od pražení; kvalita po zabalení dál klesá.</p><div class="cards">${f.catalog.map(p=>{const owner=brand(p.brand),l=p.last,total=f.lots.filter(x=>x.product===p.id).reduce((n,l)=>n+l.units,0);return `<section class="card"><div class="card-head"><h2>${esc(p.name)}</h2><span class="badge">${p.size} g · ${({testing:'Testování',released:'Uvedený produkt',failed:'Test neprošel'})[p.status]}</span></div><div class="product-bag6" data-pack="${p.pack}" style="border-color:${esc(owner.color)}"><span>${esc(owner.name)}</span><strong>${esc(p.name)}</strong><small>${p.size} g · ${PRODUCT_PACKS6[p.pack].name}</small></div><p class="sub">${esc(blend(p.blend).name)} · balení v ${esc(p.city)} · vzorek ${number(p.testQuality,1)}/100${p.status==='testing'?' · vyhodnocení T'+p.due:''}</p>${rows([['Cena za balení',money(p.price)],['Obal, tisk a práce / balení',money(productPackingCost6(p))],['Sklad / prodejny / cesta',productUnits6(p.id)+' / '+(total-productUnits6(p.id))+' ks'],['Prodané kusy minule',l?l.units:'—'],['Příspěvek prodeje minule',l?money(l.contribution):'—'],['Nevykrytá poptávka',l?l.lost:'—'],['E-shop',p.eshop?(state.projects.eshop.done&&state.departments.it?'Zapnutý':'Čeká na hotový IT projekt a pracovníka'):'Vypnutý'],['Automatické balení',p.plan.enabled?'Zapnuté · '+money(p.plan.budget)+'/týden':'Vypnuté']])}<p class="sub">${esc(p.story)}${l?.plan?'<br>'+esc(l.plan.reason):''}</p><div class="actions"><button class="soft" data-product-edit6="${p.id}">Cena, prodej a plán</button><button class="primary" data-product-pack6="${p.id}" ${p.status!=='released'?'disabled':''}>Zabalit kávu</button><button class="soft" data-product-ship6="${p.id}" ${!productUnits6(p.id)||!state.stores.some(s=>!s.franchise)?'disabled':''}>Poslat do kavárny</button><button class="quiet" data-product-stock6="${p.id}">Šarže a čerstvost</button><button class="quiet" data-product-sales6="${p.id}">Prodeje podle kanálu</button>${p.status==='failed'?`<button class="soft" data-product-retest6="${p.id}">Zopakovat test s čerstvou kávou</button>`:''}</div></section>`}).join('')||empty('Zatím nemáš hotový produkt. Vyber recepturu, značku a první 250g balení.')}</div>`;}
coffeeView=function(){return `<div class="actions" style="margin-bottom:20px"><button class="${coffeeTab6==='recipes'?'primary':'soft'}" data-coffee-tab6="recipes">Receptury kávy</button><button class="${coffeeTab6==='products'?'primary':'soft'}" data-coffee-tab6="products">Vlastní produkty a prodej</button></div>`+(coffeeTab6==='products'?productsView6():PRODUCTS_UI6.coffeeView());};
brandingView=function(){return `<div class="actions"><button class="primary" id="brandingProducts6">Hotová balení, ceny a prodej</button></div><p class="sub">Etiketa níže určuje vzhled receptury a B2B tisk. Pro kavárenský a e-shopový prodej vytvoř samostatný hotový produkt; jeho obal, gramáž, cenu a zásoby spravuješ v Kávě a vlastních produktech.</p>`+PRODUCTS_UI6.brandingView().replace('data-brand-report5="products"','data-product-report6');};
function productDevelopmentDialog6(){show(`<h2>Vyvinout vlastní produkt</h2><div class="fields">${field('Název produktu','<input id="productName6" maxlength="40" value="Moje ranní káva">')}${field('Receptura',`<select id="productBlend6">${blendOptions(state.blends[0].id)}</select>`)}${field('Značka',`<select id="productBrand6">${brandOptions(state.brands[0].id)}</select>`)}${field('Gramáž',`<select id="productSize6">${[250,500,1000].map(n=>option(n,n+' g',250)).join('')}</select>`)}${field('Obal',`<select id="productPack6">${Object.entries(PRODUCT_PACKS6).map(([k,p])=>option(k,p.name,'classic')).join('')}</select>`)}${field('Cena včetně DPH',input('productPrice6',180,50,2000))}${field('Místo balení',`<select id="productCity6">${cityOptions('Praha')}</select>`)}</div><label>Příběh produktu<textarea id="productStory6" maxlength="250" rows="2"></textarea></label><div id="productDevelopmentQuote6" class="sub"></div><button class="primary" id="productDevelopConfirm6">Zaplatit vývoj a spustit test</button>`);let q;const read=()=>({name:el('productName6').value,blend:el('productBlend6').value,brand:el('productBrand6').value,size:Number(el('productSize6').value),pack:el('productPack6').value,price:Number(el('productPrice6').value),story:el('productStory6').value,city:el('productCity6').value}),refresh=()=>{try{q=productDevelopmentQuote6(read());el('productDevelopmentQuote6').textContent='Vývoj '+money(q.fee)+', vzorek 500 g za '+money(q.sample.cost)+' ze zásob; kvalita '+number(q.sample.quality,1)+'/100. Výsledek v T'+(state.week+2)+'.';el('productDevelopConfirm6').disabled=state.cash<q.fee||state.over;}catch(e){q=null;el('productDevelopmentQuote6').textContent=e.message;el('productDevelopConfirm6').disabled=true;}};for(const id of ['productName6','productBlend6','productBrand6','productSize6','productPack6','productPrice6','productStory6','productCity6'])el(id).oninput=el(id).onchange=refresh;refresh();el('productDevelopConfirm6').onclick=()=>act(()=>{developProduct6(read(),q);el('modal').close();toast('Produkt je v testování.');render()});}
function productPackDialog6(id){const p=product6(id);show(`<h2>Zabalit · ${esc(p.name)}</h2>${field('Celá balení · '+p.size+' g',input('productPackUnits6',12,1,2000))}<div id="productPackQuote6" class="sub"></div><button class="primary" id="productPackConfirm6">Zabalit a zaplatit obaly</button>`);let q;const refresh=()=>{try{q=productPackQuote6(id,Number(el('productPackUnits6').value));el('productPackQuote6').textContent=q.units+' balení spotřebuje '+number(q.kg,2)+' kg kávy. Obaly a práce '+money(q.cost)+', zásoba po dokončení '+money(q.unitCost)+'/ks. Kvalita '+number(q.input.quality,1)+'/100. Bez hotové kávy balení nevznikne.';el('productPackConfirm6').disabled=state.cash<q.cost||state.over;}catch(e){q=null;el('productPackQuote6').textContent=e.message;el('productPackConfirm6').disabled=true;}};el('productPackUnits6').oninput=refresh;refresh();el('productPackConfirm6').onclick=()=>act(()=>{packProduct6(id,q.units,q);el('modal').close();toast('Hotová balení jsou ve skladu.');render()});}
function productShipDialog6(id){const p=product6(id);show(`<h2>Rozvoz · ${esc(p.name)}</h2><div class="fields">${field('Kavárna',`<select id="productShipStore6">${state.stores.filter(s=>!s.franchise).map(s=>option(s.id,loc(s.id).city+' · '+loc(s.id).name,state.stores[0]?.id)).join('')}</select>`)}${field('Celá balení',input('productShipUnits6',Math.min(12,productUnits6(id)),1,500))}</div><div id="productShipQuote6" class="sub"></div><button class="primary" id="productShipConfirm6">Odeslat hotová balení</button><p class="sub">Pobočka prodává produkt jen tehdy, když je povolený v jeho prodejních kanálech.</p>`);let q;const refresh=()=>{try{q=productShipQuote6(id,Number(el('productShipUnits6').value),el('productShipStore6').value);el('productShipQuote6').textContent=q.units+' ks · rozvoz '+money(q.cost)+' · dostupné od T'+q.due+'. Doprava se přičte k pořizovacímu nákladu balení.';el('productShipConfirm6').disabled=state.cash<q.cost||state.over;}catch(e){q=null;el('productShipQuote6').textContent=e.message;el('productShipConfirm6').disabled=true;}};el('productShipStore6').onchange=el('productShipUnits6').oninput=refresh;refresh();el('productShipConfirm6').onclick=()=>act(()=>{shipProduct6(id,q.units,q.store,q);el('modal').close();toast('Balíčky jsou na cestě.');render()});}
function productEditDialog6(id){const p=product6(id),plan=p.plan;show(`<h2>Prodej · ${esc(p.name)}</h2>${field('Cena včetně DPH',input('productEditPrice6',p.price,50,2000))}<label class="checkbox-line"><input id="productEshop6" type="checkbox" ${p.eshop?'checked':''}> Prodávat e-shopem z hotových zásob</label><h3>Prodejny produktu</h3>${state.stores.filter(s=>!s.franchise).map(s=>`<label class="checkbox-line"><input type="checkbox" data-product-channel6="${s.id}" ${p.stores.includes(s.id)?'checked':''}> ${esc(loc(s.id).city)} · ${esc(loc(s.id).name)}</label>`).join('')||empty('Nejdřív otevři vlastní kavárnu.')}<h3>Automatické balení a doplňování</h3><label class="checkbox-line"><input id="productAuto6" type="checkbox" ${plan.enabled?'checked':''}> Povolit balení a rozvoz po obsluze kaváren a kontraktů</label><div class="fields">${field('Cíl ve skladu / e-shop',input('productTarget6',plan.target,0,500))}${field('Cíl na každé prodejně',input('productPerStore6',plan.perStore,0,100))}${field('Týdenní rozpočet na obal a rozvoz',input('productBudget6',plan.budget,0,50000))}${field('Zachovat rezervu týdnů',input('productReserve6',plan.reserve,1,8))}</div><p class="sub">Pražírny zohlední potřebu automatického balení. Při nedostatku kávy nebo peněz se vyrobí jen dostupná celá balení. Obal a rozvoz sdílejí tento rozpočet, hotové zásoby na cestě se znovu neposílají.</p><button class="primary" id="productEditConfirm6">Uložit prodej a plán</button>`);el('productEditConfirm6').onclick=()=>act(()=>{const channels={price:Number(el('productEditPrice6').value),eshop:el('productEshop6').checked,stores:[...document.querySelectorAll('[data-product-channel6]:checked')].map(n=>n.dataset.productChannel6)},data={enabled:el('productAuto6').checked,target:Number(el('productTarget6').value),perStore:Number(el('productPerStore6').value),budget:Number(el('productBudget6').value),reserve:Number(el('productReserve6').value)};if(!Number.isInteger(channels.price)||channels.price<50||channels.price>2000||!Number.isInteger(data.target)||data.target<0||data.target>500||!Number.isInteger(data.perStore)||data.perStore<0||data.perStore>100||!Number.isInteger(data.budget)||data.budget<0||data.budget>50000||!Number.isInteger(data.reserve)||data.reserve<1||data.reserve>8)throw Error('Zkontroluj cenu, zásoby, rozpočet a rezervu.');setProductChannels6(id,channels);setProductPlan6(id,data);el('modal').close();toast('Prodej a doplňování uloženy.');render()});}
function productStockDialog6(id){const p=product6(id);show(`<h2>Šarže · ${esc(p.name)}</h2><div class="table-scroll"><table class="data"><thead><tr><th>Místo</th><th>Ks</th><th>Náklad / kus</th><th>Kvalita při balení</th><th>Praženo</th><th>Dostupnost / konec</th></tr></thead><tbody>${state.products6.lots.filter(l=>l.product===id).map(l=>`<tr><td>${l.destination==='warehouse'?esc(l.city)+' · sklad':esc(loc(l.destination).name)}<small>${esc(l.label.brandName)} · ${esc(l.label.name)}</small></td><td>${l.units}</td><td>${money(l.unitCost)}</td><td>${number(l.quality,1)}</td><td>T${l.roasted}</td><td>T${l.arrives} / T${l.expires}</td></tr>`).join('')||'<tr><td colspan="6">Žádná hotová balení.</td></tr>'}</tbody></table></div><p class="sub">Po uplynutí trvanlivosti se zásoba odepíše do výsledku firmy. Prodej nevytváří nové balení a nepřepisuje kvalitu staré kávy.</p>`);}
digestDestination6=function(x){if(x.view==='coffee')coffeeTab6='products';PRODUCTS_UI6.digestDestination6(x);};
function openProductsReport6(){el('modal').close();reportKind5='retailproducts';goto('performance');}
bind=function(){PRODUCTS_UI6.bind();on('[data-coffee-tab6]',b=>{coffeeTab6=b.dataset.coffeeTab6;render()});if(el('productNew6'))el('productNew6').onclick=productDevelopmentDialog6;if(el('productReport6'))el('productReport6').onclick=openProductsReport6;if(el('brandingProducts6'))el('brandingProducts6').onclick=()=>{coffeeTab6='products';goto('coffee')};on('[data-product-report6]',openProductsReport6);on('[data-product-edit6]',b=>productEditDialog6(b.dataset.productEdit6));on('[data-product-pack6]',b=>productPackDialog6(b.dataset.productPack6));on('[data-product-ship6]',b=>productShipDialog6(b.dataset.productShip6));on('[data-product-stock6]',b=>productStockDialog6(b.dataset.productStock6));on('[data-product-sales6]',b=>productSalesDialog6(b.dataset.productSales6));on('[data-product-retest6]',b=>{try{const q=productRetestQuote6(b.dataset.productRetest6);confirmAction('Opakovat test?','Nový vzorek 500 g · kvalita '+number(q.sample.quality,1)+'/100. Poplatek '+money(q.fee)+', výsledek za dva týdny.',()=>retestProduct6(q.id,q),'Zaplatit a opakovat');}catch(e){toast(e.message);}});};
help=function(){PRODUCTS_UI6.help();const p=document.createElement('p');p.textContent='V Kávě a vlastních produktech přepni na Vlastní produkty a prodej. Vyviň 250g, 500g nebo 1kg produkt ze skutečného vzorku, zabal upraženou kávu, pošli hotové kusy do kavárny a povol prodej. E-shop také potřebuje hotová balení. Automatické balení má rozpočet a rezervu, report odděluje kavárny a e-shop a ukazuje chybějící zásobu.';el('modalContent').append(p);};el('help').onclick=help;render();

function productSalesDialog6(id){const p=product6(id),sales=state.products6.history.flatMap(h=>h.rows.find(r=>r.id===id)?.sales||[]).slice(-40).reverse();show(`<h2>Prodeje · ${esc(p.name)}</h2><div class="table-scroll"><table class="data"><thead><tr><th>Týden / kanál</th><th>Prodáno / poptávka</th><th>Tržby bez DPH</th><th>Zásoby / prodej</th><th>Příspěvek</th></tr></thead><tbody>${sales.map(s=>`<tr><td>T${s.week} · ${s.channel==='online'?'E-shop':esc(loc(s.destination).name)}</td><td>${s.units} / ${s.wanted} ks<small>${money(s.price)} / ks · ${number(s.kg,2)} kg · kvalita ${s.quality===null?'—':number(s.quality,1)}</small></td><td>${money(s.revenue)}</td><td>${money(s.cost)} / ${money(s.handling)}</td><td>${money(s.contribution)}</td></tr>`).join('')||'<tr><td colspan="5">Zatím bez uzavřeného prodeje.</td></tr>'}</tbody></table></div><p class="sub">Příspěvek odečítá pořizovací cenu kávy, obal, balicí práci, dopravu a prodejní poplatky. Fixní mzdy, výroba a daň celé firmy jsou ve firemním výsledku.</p>`);}

performanceDetail5=function(id){PRODUCTS_UI6.performanceDetail5(id);if(reportKind5==='retailproducts'&&el('reportManage5'))el('reportManage5').onclick=()=>{el('modal').close();coffeeTab6='products';goto('coffee');};};
